import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.D3fmyz3M.js";const u=JSON.parse('{"title":"精通总览","description":"从会用 API 到能读源码、做主迁移、查疑难故障。","frontmatter":{"title":"精通总览","description":"从会用 API 到能读源码、做主迁移、查疑难故障。"},"headers":[],"relativePath":"mastery/index.md","filePath":"mastery/index.md","lastUpdated":1792674288000}'),l={name:"mastery/index.md"};function o(d,a,n,s,h,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="精通总览" tabindex="-1">精通总览 <a class="header-anchor" href="#精通总览" aria-label="Permalink to &quot;精通总览&quot;">​</a></h1><p>“精通微前端”不是记住七个库的 API，而是具备四种能力：</p><table tabindex="0"><thead><tr><th>能力</th><th>表现</th><th>章节</th></tr></thead><tbody><tr><td>读源码</td><td>能定位加载、沙箱、路由的关键实现</td><td><a href="/micro-frontend-docs/mastery/source-analysis">源码级剖析</a></td></tr><tr><td>做迁移</td><td>能把老系统渐进迁移且可回滚</td><td><a href="/micro-frontend-docs/mastery/migration">迁移路线</a></td></tr><tr><td>查故障</td><td>能根据现象快速定位根因</td><td><a href="/micro-frontend-docs/mastery/troubleshooting">故障手册</a></td></tr><tr><td>做决策</td><td>能写出有依据的选型报告</td><td><a href="/micro-frontend-docs/mastery/comparison">选型对比</a></td></tr></tbody></table><h2 id="能力自测" tabindex="-1">能力自测 <a class="header-anchor" href="#能力自测" aria-label="Permalink to &quot;能力自测&quot;">​</a></h2><h3 id="入门" tabindex="-1">入门 <a class="header-anchor" href="#入门" aria-label="Permalink to &quot;入门&quot;">​</a></h3><ul><li>能跑通任意一套示例。</li><li>能解释 props 与全局状态的区别。</li><li>能说出 iframe 的三个缺点。</li></ul><h3 id="熟练" tabindex="-1">熟练 <a class="header-anchor" href="#熟练" aria-label="Permalink to &quot;熟练&quot;">​</a></h3><ul><li>能独立接入一个 qiankun 或 micro-app 子应用。</li><li>能定位样式污染与路由 404。</li><li>能配置 CORS 与 UMD 构建。</li><li>能设计一套通信契约。</li></ul><h3 id="精通" tabindex="-1">精通 <a class="header-anchor" href="#精通" aria-label="Permalink to &quot;精通&quot;">​</a></h3><ul><li>能读 single-spa 的 reroute 流程。</li><li>能解释 qiankun Proxy 沙箱的 <code>with</code> 包裹。</li><li>能设计灰度与回滚方案。</li><li>能在故障现场根据日志定位到具体子应用与版本。</li><li>能写出包含成本、风险、收益的选型报告。</li></ul><h2 id="学习方式" tabindex="-1">学习方式 <a class="header-anchor" href="#学习方式" aria-label="Permalink to &quot;学习方式&quot;">​</a></h2><ol><li><strong>读源码</strong>：不要逐行读，带着问题读。</li><li><strong>做实验</strong>：每读一个机制，就在示例里制造一次对应故障。</li><li><strong>写复盘</strong>：把排查过程写成文档，形成团队资产。</li><li><strong>做迁移</strong>：真实迁移一次，胜过读十篇文章。</li></ol><h2 id="推荐顺序" tabindex="-1">推荐顺序 <a class="header-anchor" href="#推荐顺序" aria-label="Permalink to &quot;推荐顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原理 → 示例 → 源码 → 故障 → 迁移 → 选型</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果时间有限，优先补：</p><ol><li>路由与加载（最高频故障）。</li><li>样式隔离（最隐蔽）。</li><li>监控与回滚（上线必需）。</li></ol><p>继续阅读：<a href="/micro-frontend-docs/mastery/source-analysis">源码级剖析</a>。</p>',17)])])}const m=t(l,[["render",o]]);export{u as __pageData,m as default};
